{"term":"ballbuster","lang":"en","script":"latin","romanization":null,"category":"insults","subcategory":"emasculation","concept":"emasculating_person","is_novel_concept":false,"register":"slang_crude","crude":70,"technical":5,"recognition_pct_current":82,"recognition_pct_peak":88,"peak_year":null,"regional":null,"definition":"A person—typically a woman or a demanding authority figure—perceived as destroying a man's confidence, ease, or sexual dominance through relentless demands or criticism.","english_term":"ballbuster","english_translation_quality":"direct","notes":"Can extend to any exhausting situation ('that job is a real ballbuster'); primary insult targets emasculating behavior; 'balls' = testicles = male potency in metaphor."}
{"term":"ball-breaker","lang":"en","script":"latin","romanization":null,"category":"insults","subcategory":"emasculation","concept":"emasculating_person","is_novel_concept":false,"register":"slang_crude","crude":70,"technical":5,"recognition_pct_current":78,"recognition_pct_peak":83,"peak_year":null,"regional":null,"definition":"A person who emasculates others or who is exceptionally demanding and difficult; hyphenated variant of ballbuster with identical meaning and usage.","english_term":"ballbuster","english_translation_quality":"direct","notes":"Interchangeable with 'ballbuster'; hyphen is the only distinction; both forms appear in print; neither form has clear dominance by region."}
{"term":"dickless","lang":"en","script":"latin","romanization":null,"category":"insults","subcategory":"phallic_inadequacy","concept":"phallic_inadequacy_insult","is_novel_concept":false,"register":"slang_crude","crude":75,"technical":5,"recognition_pct_current":75,"recognition_pct_peak":75,"peak_year":null,"regional":null,"definition":"Pejorative for a cowardly or ineffectual person, equating the literal or figurative absence of a penis with lack of courage or competence.","english_term":"dickless","english_translation_quality":"direct","notes":"Explicitly male-coded; can target men (implying they lack masculine grit) or occasionally women (as crude negation of authority); logic mirrors 'spineless' but anchors to genital anatomy."}
